const SPECIES=[
{id:'tubarao-branco',name:'Tubarão-branco',sci:'Carcharodon carcharias',group:'Peixes',depth:'0–1.200 m',habitat:'Mares temperados e subtropicais',size:'Até ~6,4 m',status:'Vulnerável',type:'shark',desc:'Predador de topo de ampla distribuição e alta mobilidade, associado a redes tróficas costeiras e oceânicas.',diet:'Peixes, raias, cefalópodes e, em adultos, mamíferos marinhos.',behavior:'Usa visão, olfato, mecanorrecepção e eletrorecepção; pode realizar grandes deslocamentos.',threats:['captura incidental','pesca dirigida','degradação de habitat'],facts:['A espécie apresenta baixa produtividade populacional relativa.','Juvenis e adultos ocupam habitats diferentes ao longo da vida.','A eletrorecepção ajuda a detectar campos elétricos produzidos por presas.'],source:'https://www.fisheries.noaa.gov/species/white-shark'},
{id:'orca',name:'Orca',sci:'Orcinus orca',group:'Mamíferos',depth:'Superfície–profundidade',habitat:'Oceanos polares, temperados e tropicais',size:'Até ~9,8 m',status:'Dados variáveis',type:'orca',desc:'Cetáceo odontoceto social, conhecido por comunicação complexa e estratégias de caça aprendidas.',diet:'Peixes, lulas, aves e mamíferos marinhos, conforme a população.',behavior:'Vive em grupos sociais e apresenta repertórios vocais e comportamentais que podem variar regionalmente.',threats:['ruído subaquático','contaminantes','redução de presas'],facts:['É um golfinho oceânico de grande porte.','Ecótipos podem apresentar dietas e comportamentos distintos.','Comportamentos podem ser transmitidos socialmente dentro de grupos.'],source:'https://www.fisheries.noaa.gov/whales'},
{id:'baleia-azul',name:'Baleia-azul',sci:'Balaenoptera musculus',group:'Mamíferos',depth:'Superfície–profundidade',habitat:'Todos os oceanos, exceto o Ártico',size:'Até ~33,5 m',status:'Em perigo',type:'whale',desc:'O maior animal conhecido da Terra; alimenta-se principalmente de krill por filtração.',diet:'Principalmente krill.',behavior:'Realiza migrações sazonais e utiliza vocalizações de baixa frequência.',threats:['colisões com embarcações','emalhamento','ruído oceânico'],facts:['Populações foram severamente reduzidas pela caça comercial histórica.','Vocalizações de baixa frequência podem percorrer grandes distâncias.','Grandes concentrações de krill sustentam períodos intensos de alimentação.'],source:'https://www.fisheries.noaa.gov/species/blue-whale'},
{id:'lula-gigante',name:'Lula-gigante',sci:'Architeuthis dux',group:'Moluscos',depth:'Mesopelágica–batipelágica',habitat:'Oceanos profundos',size:'Grandes dimensões; estimativas variam',status:'Pouco conhecida',type:'squid',desc:'Cefalópode de águas profundas conhecido por espécimes e observações raras.',diet:'Provavelmente peixes e outros cefalópodes.',behavior:'Vive em águas profundas e possui olhos extremamente grandes.',threats:['conhecimento insuficiente'],facts:['Seus olhos estão entre os maiores conhecidos no reino animal.','Grande parte de sua biologia ainda é difícil de observar em ambiente natural.','Braços e tentáculos são especializados na captura e manipulação de presas.'],source:'https://ocean.si.edu/ocean-life/invertebrates/octopuses-squids-and-relatives'},
{id:'polvo-comum',name:'Polvo-comum',sci:'Octopus vulgaris',group:'Moluscos',depth:'Costeiro–mesopelágico',habitat:'Fundos rochosos e arenosos',size:'Varia regionalmente',status:'Varia por avaliação',type:'octopus',desc:'Cefalópode bentônico com grande capacidade de aprendizagem, manipulação e mudança de aparência.',diet:'Crustáceos, moluscos e outros pequenos animais.',behavior:'Usa camuflagem, toca e manipulação de objetos para alimentação e defesa.',threats:['pesca','alterações costeiras'],facts:['A pele pode mudar de cor, padrão e textura.','O sistema nervoso é altamente distribuído pelos braços.','Grande parte de sua atividade acontece rente ao fundo.'],source:'https://ocean.si.edu/ocean-life/invertebrates/octopuses-squids-and-relatives'},
{id:'cavalo-marinho',name:'Cavalo-marinho',sci:'Hippocampus spp.',group:'Peixes',depth:'Raso',habitat:'Pradarias marinhas, recifes e estuários',size:'Depende da espécie',status:'Varia por espécie',type:'seahorse',desc:'Peixes singnatídeos especializados, com postura ereta e cauda preênsil.',diet:'Pequenos crustáceos e zooplâncton.',behavior:'Move-se lentamente e pode se prender à vegetação com a cauda.',threats:['perda de habitat','captura','poluição costeira'],facts:['Nos cavalos-marinhos, o macho recebe os ovos e realiza a gestação.','Hippocampus reúne várias espécies.','A cauda preênsil facilita a fixação em vegetação e substratos.'],source:'https://www.fisheries.noaa.gov/'},
{id:'tartaruga-verde',name:'Tartaruga-verde',sci:'Chelonia mydas',group:'Répteis',depth:'Superfície–costeiro',habitat:'Águas tropicais e subtropicais',size:'Até ~1,2 m de carapaça',status:'Em perigo',type:'turtle',desc:'Tartaruga marinha cujo ciclo de vida conecta praias de desova, áreas costeiras e oceânicas.',diet:'Juvenis são mais onívoros; adultos frequentemente consomem algas e fanerógamas.',behavior:'Realiza migrações entre áreas de alimentação e reprodução.',threats:['captura incidental','perda de praias','poluição'],facts:['É uma das tartarugas marinhas mais amplamente distribuídas.','A dieta adulta pode contribuir para a dinâmica das pradarias marinhas.','A vida da espécie conecta habitats costeiros diferentes.'],source:'https://www.fisheries.noaa.gov/'},
{id:'peixe-lua',name:'Peixe-lua',sci:'Mola mola',group:'Peixes',depth:'Superfície–profundidade',habitat:'Oceanos temperados e tropicais',size:'Pode ultrapassar 2 m',status:'Varia por avaliação',type:'mola',desc:'Peixe ósseo de formato incomum, com corpo comprimido e grandes nadadeiras dorsal e anal.',diet:'Dieta ampla, incluindo organismos gelatinosos e outros invertebrados.',behavior:'Pode realizar deslocamentos verticais e horizontais importantes.',threats:['captura incidental','plásticos'],facts:['É um dos maiores peixes ósseos conhecidos.','Sua forma corporal representa uma história evolutiva singular.','Pode ser observado próximo à superfície e em águas mais profundas.'],source:'https://www.fisheries.noaa.gov/'},
{id:'narval',name:'Narval',sci:'Monodon monoceros',group:'Mamíferos',depth:'Superfície–profundo',habitat:'Ártico',size:'Até ~5 m',status:'Quase ameaçado',type:'narwhal',desc:'Cetáceo ártico conhecido pelo longo dente helicoidal presente principalmente nos machos.',diet:'Peixes, lulas e outros organismos marinhos.',behavior:'Vive em grupos e utiliza ecolocalização para navegar e encontrar alimento.',threats:['mudanças no gelo marinho','ruído','pressão de caça em algumas regiões'],facts:['O “chifre” é um dente alongado.','É altamente associado a ambientes com gelo marinho.','A fisiologia é especializada para águas frias do Ártico.'],source:'https://www.fisheries.noaa.gov/whales'},
{id:'peixe-pescador',name:'Peixe-pescador-abissal',sci:'Melanocetus johnsonii',group:'Águas profundas',depth:'~200–2.000 m',habitat:'Mar aberto profundo',size:'Pequeno; fêmeas maiores que machos',status:'Pouco conhecido',type:'angler',desc:'Peixe abissal famoso pelo ilício bioluminescente usado para atrair presas.',diet:'Pequenos peixes e invertebrados.',behavior:'Estratégia de emboscada; utiliza bioluminescência e boca expansível.',threats:['conhecimento insuficiente'],facts:['A bioluminescência está associada ao órgão da isca.','Machos e fêmeas podem diferir fortemente em tamanho.','A emboscada economiza energia em um ambiente de poucos recursos.'],source:'https://ocean.si.edu/ocean-life/fish/bioluminescence'},
{id:'caranguejo-yeti',name:'Caranguejo-yeti',sci:'Kiwa hirsuta',group:'Crustáceos',depth:'Fontes hidrotermais',habitat:'Fundo oceânico profundo',size:'Poucos centímetros',status:'Pouco conhecido',type:'crab',desc:'Crustáceo associado a ambientes profundos e notável pelos apêndices densamente setosos.',diet:'Matéria orgânica e possíveis relações com microrganismos.',behavior:'Associado a habitats extremos próximos a fontes hidrotermais.',threats:['alteração de habitats profundos','mineração potencial'],facts:['O nome popular faz referência ao aspecto peludo das pernas.','Fontes hidrotermais sustentam cadeias alimentares que não dependem diretamente da luz.','Microrganismos associados aos apêndices são parte de relações ecológicas relevantes.'],source:'https://ocean.si.edu/'},
{id:'agua-viva-juba-de-leao',name:'Água-viva-juba-de-leão',sci:'Cyanea capillata',group:'Cnidários',depth:'Superfície–mesopelágica',habitat:'Águas frias do Atlântico e Pacífico',size:'Varia muito',status:'Não avaliada globalmente',type:'jelly',desc:'Grande cifozoário com numerosos tentáculos, encontrado sobretudo em águas frias.',diet:'Zooplâncton e pequenos animais marinhos.',behavior:'Predação por contato usando células urticantes.',threats:['mudanças ambientais','interações costeiras'],facts:['Os tentáculos possuem cnidócitos especializados na captura de presas.','Tamanho e coloração variam.','É um exemplo de estratégia predatória passiva em organismos gelatinosos.'],source:'https://ocean.si.edu/'}
,{id:'tubarao-baleia',name:'Tubarão-baleia',sci:'Rhincodon typus',group:'Peixes',depth:'0–1.900 m',habitat:'Mar aberto tropical e subtropical',size:'Comumente 8–12 m; registros maiores',status:'Em perigo',type:'shark',desc:'O maior peixe vivo conhecido. Apesar do tamanho, alimenta-se por filtração de plâncton e pequenos organismos.',diet:'Filtrador: plâncton, ovos de peixe, pequenos peixes e crustáceos.',behavior:'Nada lentamente perto da superfície, mas realiza mergulhos profundos; agrega-se em locais e épocas de alta oferta de alimento.',threats:['captura incidental','colisão com embarcações','pesca dirigida em algumas regiões'],facts:['O padrão de manchas do dorso é individual e permite identificar cada animal.','Agregações sazonais coincidem com eventos de desova e picos de produtividade.','Mergulhos profundos são registrados por marcadores eletrônicos.'],source:'https://www.fisheries.noaa.gov/species/whale-shark',sourceLabel:'NOAA Fisheries'},
{id:'tubarao-martelo',name:'Tubarão-martelo-recortado',sci:'Sphyrna lewini',group:'Peixes',depth:'0–1.000 m',habitat:'Águas costeiras e oceânicas tropicais e temperadas',size:'Até ~4 m',status:'Criticamente em perigo',type:'shark',desc:'Tubarão de cabeça achatada e alargada, que amplia a superfície de sensores usados na busca por presas.',diet:'Peixes ósseos, cefalópodes, raias e outros elasmobrânquios.',behavior:'Jovens podem formar grandes cardumes em montes submarinos; adultos são mais solitários.',threats:['pesca dirigida','captura incidental','remoção de nadadeiras'],facts:['A cabeça em forma de martelo distribui os poros sensoriais numa área maior.','Baías costeiras rasas funcionam como áreas de berçário.','Está listada em apêndices de convenções internacionais de comércio.'],source:'https://www.iucnredlist.org/',sourceLabel:'IUCN Red List'},
{id:'tubarao-mako',name:'Tubarão-mako',sci:'Isurus oxyrinchus',group:'Peixes',depth:'0–750 m',habitat:'Mar aberto temperado e tropical',size:'Até ~4 m',status:'Em perigo',type:'shark',desc:'Tubarão pelágico de corpo hidrodinâmico, associado às maiores velocidades registradas entre tubarões.',diet:'Peixes pelágicos, cefalópodes e, ocasionalmente, outros tubarões.',behavior:'Nadador rápido e migrador; mantém temperatura muscular acima da água ao redor.',threats:['captura incidental em pesca de superfície','pesca dirigida'],facts:['Possui endotermia regional: aquece músculos, vísceras e olhos.','Realiza migrações que cruzam bacias oceânicas inteiras.','A baixa taxa reprodutiva torna a recuperação populacional lenta.'],source:'https://www.fisheries.noaa.gov/species/shortfin-mako-shark',sourceLabel:'NOAA Fisheries'},
{id:'tubarao-groenlandia',name:'Tubarão-da-groenlândia',sci:'Somniosus microcephalus',group:'Peixes',depth:'0–2.200 m',habitat:'Ártico e Atlântico Norte frio',size:'Até ~5 m',status:'Vulnerável',type:'shark',desc:'Tubarão de águas frias e movimentos lentos, associado às maiores longevidades estimadas entre vertebrados.',diet:'Peixes, carcaças e presas variadas capturadas ou consumidas como carniça.',behavior:'Metabolismo lento em água próxima de 0 °C; ocupa desde a superfície polar até grandes profundidades.',threats:['captura incidental','mudanças no Ártico'],facts:['Estimativas de idade por datação do cristalino sugerem séculos de vida.','A maturidade sexual parece ocorrer muito tarde na vida do animal.','Muitos indivíduos apresentam parasitas fixados nos olhos.'],source:'https://www.iucnredlist.org/',sourceLabel:'IUCN Red List'},
{id:'raia-manta',name:'Raia-manta-oceânica',sci:'Mobula birostris',group:'Peixes',depth:'0–1.000 m',habitat:'Mar aberto tropical e subtropical',size:'Até ~7 m de envergadura',status:'Em perigo',type:'ray',desc:'A maior raia conhecida. Filtra plâncton em movimento contínuo, usando lobos cefálicos para direcionar a água.',diet:'Filtrador: zooplâncton e pequenos organismos pelágicos.',behavior:'Visita estações de limpeza em recifes e realiza mergulhos profundos entre períodos de alimentação.',threats:['pesca dirigida por brânquias','captura incidental','perturbação em áreas de agregação'],facts:['As marcas ventrais funcionam como identidade individual.','Alterna longas permanências em superfície com mergulhos de centenas de metros.','A reprodução é lenta, com poucos filhotes ao longo da vida.'],source:'https://www.iucnredlist.org/',sourceLabel:'IUCN Red List'},
{id:'enguia-lobo',name:'Enguia-lobo',sci:'Anarrhichthys ocellatus',group:'Peixes',depth:'0–225 m',habitat:'Costões rochosos do Pacífico Norte',size:'Até ~2,4 m',status:'Não avaliada globalmente',type:'fish',desc:'Peixe alongado de tocas rochosas, com mandíbulas e dentes adaptados a presas de carapaça dura.',diet:'Ouriços, caranguejos, moluscos e outros invertebrados de casca dura.',behavior:'Ocupa fendas e tocas por longos períodos; casais podem permanecer no mesmo abrigo.',threats:['degradação de habitat costeiro','pesca incidental'],facts:['Apesar do nome, não é uma enguia verdadeira.','Os dentes frontais e as placas faríngeas trituram carapaças.','O consumo de ouriços conecta a espécie à dinâmica das florestas de kelp.'],source:'https://ocean.si.edu/',sourceLabel:'Smithsonian Ocean'},
{id:'peixe-palhaco',name:'Peixe-palhaço',sci:'Amphiprion ocellaris',group:'Peixes',depth:'1–15 m',habitat:'Recifes de coral do Indo-Pacífico',size:'Até ~11 cm',status:'Pouco preocupante',type:'fish',desc:'Peixe recifal que vive associado a anêmonas, protegido dos tentáculos urticantes por uma camada de muco.',diet:'Zooplâncton, algas e restos de alimento.',behavior:'Vive em pequenos grupos hierárquicos dentro de uma única anêmona hospedeira.',threats:['coleta para aquariofilia','branqueamento e perda de recifes'],facts:['A relação com a anêmona é um exemplo clássico de mutualismo.','O grupo é organizado por tamanho, com uma fêmea dominante.','São hermafroditas protândricos: podem mudar de sexo ao longo da vida.'],source:'https://ocean.si.edu/',sourceLabel:'Smithsonian Ocean'},
{id:'bodiao-limpador',name:'Bodião-limpador',sci:'Labroides dimidiatus',group:'Peixes',depth:'1–40 m',habitat:'Recifes de coral do Indo-Pacífico',size:'Até ~11 cm',status:'Pouco preocupante',type:'fish',desc:'Peixe pequeno que mantém “estações de limpeza” onde remove parasitas e tecido morto de outros peixes.',diet:'Ectoparasitas, muco e tecido de peixes-clientes.',behavior:'Ocupa um território fixo; peixes maiores visitam voluntariamente e permitem a inspeção.',threats:['degradação de recifes','coleta para aquariofilia'],facts:['Clientes de espécies muito diferentes reconhecem e voltam à mesma estação.','A remoção experimental de limpadores altera a comunidade de peixes local.','É um dos exemplos mais estudados de mutualismo em recifes.'],source:'https://ocean.si.edu/',sourceLabel:'Smithsonian Ocean'},
{id:'atum-rabilho',name:'Atum-rabilho',sci:'Thunnus thynnus',group:'Peixes',depth:'0–1.000 m',habitat:'Atlântico Norte e Mediterrâneo',size:'Até ~3 m',status:'Pouco preocupante (reavaliado em 2021)',type:'fish',desc:'Grande peixe pelágico migratório, com musculatura e circulação adaptadas ao nado contínuo em alta velocidade.',diet:'Peixes cardumeiros, cefalópodes e crustáceos.',behavior:'Cruza o Atlântico entre áreas de alimentação e desova; mergulha centenas de metros em busca de presas.',threats:['pressão pesqueira histórica','mudanças na distribuição de presas'],facts:['Possui endotermia regional, mantendo o corpo mais quente que a água.','Marcadores eletrônicos revelaram migrações transatlânticas repetidas.','A avaliação de conservação mudou ao longo do tempo com a gestão pesqueira.'],source:'https://www.iucnredlist.org/',sourceLabel:'IUCN Red List'},
{id:'sardinha-verdadeira',name:'Sardinha-verdadeira',sci:'Sardinella brasiliensis',group:'Peixes',depth:'0–100 m',habitat:'Plataforma continental do Atlântico Sul ocidental',size:'Até ~25 cm',status:'Depende do estoque avaliado',type:'fish',desc:'Peixe pequeno e cardumeiro que transfere energia do plâncton para predadores maiores na plataforma continental.',diet:'Fitoplâncton e zooplâncton.',behavior:'Forma grandes cardumes; a abundância varia fortemente com as condições oceanográficas.',threats:['sobrepesca','variabilidade ambiental','alterações na ressurgência'],facts:['Espécies forrageiras como esta sustentam grande parte das teias alimentares costeiras.','Estoques podem oscilar muito entre anos.','É um dos recursos pesqueiros mais importantes do Sudeste do Brasil.'],source:'https://www.fao.org/fishery/en',sourceLabel:'FAO Fisheries'},
{id:'mero',name:'Mero',sci:'Epinephelus itajara',group:'Peixes',depth:'0–100 m',habitat:'Recifes, manguezais e estruturas costeiras do Atlântico',size:'Até ~2,5 m',status:'Vulnerável (reavaliado em 2018)',type:'fish',desc:'Grande garoupa de vida longa, associada a manguezais quando jovem e a estruturas recifais quando adulta.',diet:'Crustáceos, peixes e outros invertebrados capturados por sucção.',behavior:'Forma agregações reprodutivas previsíveis, o que aumenta a vulnerabilidade à pesca.',threats:['pesca dirigida','perda de manguezais','captura em agregações'],facts:['Emite sons de baixa frequência produzidos pela bexiga natatória.','Os manguezais funcionam como berçário essencial para os juvenis.','A pesca é proibida ou restrita em vários países, incluindo o Brasil.'],source:'https://www.iucnredlist.org/',sourceLabel:'IUCN Red List'},
{id:'peixe-voador',name:'Peixe-voador',sci:'Exocoetus volitans',group:'Peixes',depth:'0–20 m',habitat:'Camada superficial de oceanos tropicais',size:'Até ~30 cm',status:'Pouco preocupante',type:'fish',desc:'Peixe pelágico que escapa de predadores planando sobre a superfície com nadadeiras peitorais expandidas.',diet:'Zooplâncton e pequenos organismos de superfície.',behavior:'Ganha velocidade sob a água e usa a cauda para impulsionar planeios sucessivos.',threats:['captura incidental','poluição de superfície'],facts:['O planeio é impulsionado pela cauda batendo na superfície, não por um voo ativo.','Vive na fina camada onde predadores vêm de baixo e de cima.','Os ovos costumam ser fixados a materiais flutuantes.'],source:'https://www.fishbase.se/',sourceLabel:'FishBase'},
{id:'celacanto',name:'Celacanto',sci:'Latimeria chalumnae',group:'Peixes',depth:'~150–700 m',habitat:'Cavernas submarinas de encostas vulcânicas',size:'Até ~2 m',status:'Criticamente em perigo',type:'fish',desc:'Peixe de nadadeiras lobadas conhecido primeiro por fósseis e reencontrado vivo no século XX.',diet:'Peixes e cefalópodes capturados em movimentos lentos.',behavior:'Passa o dia em cavernas e sai à noite; desloca-se lentamente com nadadeiras pareadas.',threats:['captura incidental','população reduzida e restrita'],facts:['Foi identificado vivo em 1938, depois de ser conhecido apenas por fósseis.','As nadadeiras lobadas ajudam a entender a anatomia de vertebrados antigos.','Uma segunda espécie do gênero foi descrita na Indonésia.'],source:'https://www.iucnredlist.org/',sourceLabel:'IUCN Red List'},
{id:'peixe-lanterna',name:'Peixe-lanterna',sci:'Myctophidae',group:'Peixes',depth:'200–1.000 m (sobe à noite)',habitat:'Zona mesopelágica de todos os oceanos',size:'Geralmente 2–15 cm',status:'Varia por espécie',type:'lantern',desc:'Família de pequenos peixes mesopelágicos com fotóforos, protagonista da maior migração diária de biomassa do planeta.',diet:'Zooplâncton, sobretudo copépodes e crustáceos pequenos.',behavior:'Sobe à superfície à noite para se alimentar e desce ao amanhecer para escapar de predadores visuais.',threats:['interesse crescente por pesca mesopelágica','mudanças na produtividade'],facts:['O padrão de fotóforos difere entre espécies e ajuda na identificação.','Formam boa parte da “camada de dispersão profunda” detectada por sonar.','A migração vertical transporta carbono da superfície para águas profundas.'],source:'https://www.mbari.org/',sourceLabel:'MBARI'},
{id:'caracol-do-mar-hadal',name:'Caracol-do-mar-hadal',sci:'Pseudoliparis swirei',group:'Peixes',depth:'~6.900–8.000 m',habitat:'Fossa das Marianas',size:'Cerca de 25 cm',status:'Pouco conhecido',type:'fish',desc:'Peixe de corpo gelatinoso que vive entre os ambientes mais profundos onde peixes já foram registrados.',diet:'Pequenos crustáceos anfípodes do fundo da fossa.',behavior:'Vive próximo ao sedimento, em pressão superior a 700 atmosferas.',threats:['conhecimento insuficiente','impactos potenciais em fossas profundas'],facts:['Registros de peixes nessas fossas estão perto do limite fisiológico proposto para vertebrados.','O corpo tem pouca musculatura densa e muito tecido gelatinoso.','Foi descrito a partir de imagens e coletas com armadilhas autônomas.'],source:'https://www.whoi.edu/',sourceLabel:'Woods Hole Oceanographic Institution'},
{id:'baleia-jubarte',name:'Baleia-jubarte',sci:'Megaptera novaeangliae',group:'Mamíferos',depth:'Superfície–~200 m',habitat:'Todos os oceanos; migra entre polos e trópicos',size:'Até ~16 m',status:'Pouco preocupante (globalmente)',type:'whale',desc:'Baleia de barbatanas peitorais muito longas, conhecida pelos cantos complexos e por técnicas cooperativas de alimentação.',diet:'Krill e pequenos peixes cardumeiros.',behavior:'Migra entre áreas polares de alimentação e áreas tropicais de reprodução; usa redes de bolhas para concentrar presas.',threats:['emalhamento em redes','colisão com embarcações','ruído'],facts:['Machos cantam sequências que mudam ao longo das temporadas.','A rede de bolhas é um comportamento aprendido e compartilhado.','Populações se recuperaram após o fim da caça comercial em várias regiões.'],source:'https://www.fisheries.noaa.gov/species/humpback-whale',sourceLabel:'NOAA Fisheries'},
{id:'cachalote',name:'Cachalote',sci:'Physeter macrocephalus',group:'Mamíferos',depth:'0–2.000 m ou mais',habitat:'Águas profundas de todos os oceanos',size:'Até ~18 m',status:'Vulnerável',type:'whale',desc:'O maior predador com dentes do planeta, especializado em mergulhos profundos e prolongados atrás de cefalópodes.',diet:'Lulas de profundidade e peixes.',behavior:'Mergulha por dezenas de minutos usando ecolocalização; grupos sociais de fêmeas e jovens são estáveis.',threats:['emalhamento','colisões','ruído e poluição química'],facts:['Possui o maior cérebro conhecido entre os animais.','Marcas de ventosas em sua pele indicam encontros com lulas grandes.','O órgão do espermacete participa da produção e do direcionamento do som.'],source:'https://www.fisheries.noaa.gov/species/sperm-whale',sourceLabel:'NOAA Fisheries'},
{id:'golfinho-nariz-de-garrafa',name:'Golfinho-nariz-de-garrafa',sci:'Tursiops truncatus',group:'Mamíferos',depth:'0–300 m',habitat:'Águas costeiras e oceânicas temperadas e tropicais',size:'Até ~4 m',status:'Pouco preocupante',type:'dolphin',desc:'Odontoceto costeiro e oceânico com repertório vocal complexo e comportamentos de forrageio muito variados.',diet:'Peixes, cefalópodes e crustáceos.',behavior:'Vive em grupos com composição variável; usa ecolocalização e assobios individuais.',threats:['captura incidental','poluição costeira','perturbação por embarcações'],facts:['Cada indivíduo desenvolve um assobio-assinatura que funciona como identificação.','Algumas populações usam esponjas como ferramenta de proteção do focinho.','Populações costeiras e oceânicas podem diferir em dieta e morfologia.'],source:'https://www.fisheries.noaa.gov/species/common-bottlenose-dolphin',sourceLabel:'NOAA Fisheries'},
{id:'foca-de-weddell',name:'Foca-de-weddell',sci:'Leptonychotes weddellii',group:'Mamíferos',depth:'0–600 m',habitat:'Gelo marinho costeiro da Antártica',size:'Até ~3 m',status:'Pouco preocupante',type:'seal',desc:'Foca antártica que vive associada ao gelo fixo e mantém buracos de respiração abertos para mergulhar sob a camada congelada.',diet:'Peixes antárticos, lulas e invertebrados.',behavior:'Realiza mergulhos longos sob o gelo; usa os dentes para manter aberturas de respiração.',threats:['mudanças no gelo marinho','alterações na disponibilidade de presas'],facts:['É o mamífero que se reproduz mais ao sul do planeta.','Mergulhos podem ultrapassar uma hora em condições favoráveis.','Reservas de oxigênio no sangue e músculo sustentam apneias longas.'],source:'https://ocean.si.edu/',sourceLabel:'Smithsonian Ocean'},
{id:'morsa',name:'Morsa',sci:'Odobenus rosmarus',group:'Mamíferos',depth:'0–100 m',habitat:'Plataformas rasas do Ártico',size:'Até ~3,5 m',status:'Vulnerável',type:'seal',desc:'Pinípede ártico de presas longas, que se alimenta no fundo raso e usa o gelo marinho como plataforma de descanso.',diet:'Bivalves e outros invertebrados bentônicos.',behavior:'Localiza presas enterradas usando as vibrissas e sucção; forma grandes agrupamentos.',threats:['redução do gelo marinho','perturbação em locais de descanso'],facts:['As presas são caninos superiores muito alongados, usados em disputas e para subir no gelo.','As vibrissas do focinho detectam moluscos enterrados no sedimento.','A perda de gelo força agrupamentos maiores em terra firme.'],source:'https://www.fisheries.noaa.gov/',sourceLabel:'NOAA Fisheries'},
{id:'tartaruga-de-couro',name:'Tartaruga-de-couro',sci:'Dermochelys coriacea',group:'Répteis',depth:'0–1.200 m',habitat:'Oceanos tropicais a subpolares',size:'Até ~2 m de comprimento',status:'Vulnerável (varia por população)',type:'turtle',desc:'A maior tartaruga viva, sem carapaça óssea rígida, capaz de mergulhos muito profundos atrás de presas gelatinosas.',diet:'Principalmente águas-vivas e outros organismos gelatinosos.',behavior:'Cruza bacias oceânicas inteiras entre áreas de alimentação e praias de desova.',threats:['captura incidental','ingestão de plástico','perda de praias de desova'],facts:['Mantém temperatura corporal acima da água graças ao tamanho e ao isolamento.','A carapaça é coberta por pele coriácea, não por escudos ósseos.','Algumas subpopulações estão em situação muito mais crítica que a média global.'],source:'https://www.fisheries.noaa.gov/species/leatherback-turtle',sourceLabel:'NOAA Fisheries'},
{id:'tartaruga-de-pente',name:'Tartaruga-de-pente',sci:'Eretmochelys imbricata',group:'Répteis',depth:'0–90 m',habitat:'Recifes de coral tropicais',size:'Até ~1 m de carapaça',status:'Criticamente em perigo',type:'turtle',desc:'Tartaruga recifal de bico estreito, especializada em esponjas — uma dieta rara entre vertebrados marinhos.',diet:'Esponjas e outros invertebrados sésseis.',behavior:'Permanece associada a recifes; usa o bico para alcançar presas em fendas.',threats:['comércio histórico de casco','perda de recifes','captura incidental'],facts:['O consumo de esponjas influencia a competição por espaço no recife.','O casco foi explorado por séculos no comércio de “tartaruga”.','Depende de recifes saudáveis durante quase toda a vida adulta.'],source:'https://www.iucnredlist.org/',sourceLabel:'IUCN Red List'},
{id:'pinguim-imperador',name:'Pinguim-imperador',sci:'Aptenodytes forsteri',group:'Aves marinhas',depth:'0–550 m',habitat:'Gelo marinho da Antártica',size:'Até ~1,2 m',status:'Quase ameaçado',type:'penguin',desc:'A maior espécie de pinguim, que se reproduz sobre o gelo durante o inverno antártico e mergulha centenas de metros.',diet:'Peixes antárticos, krill e lulas.',behavior:'Forma colônias densas e se agrupa para conservar calor; machos incubam o ovo sobre os pés.',threats:['perda de gelo marinho estável','mudanças na disponibilidade de presas'],facts:['Reproduz-se no inverno mais rigoroso do planeta.','Mergulhos podem passar de 500 m e durar mais de 20 minutos.','A colônia depende de gelo fixo que permaneça estável durante toda a estação.'],source:'https://www.iucnredlist.org/',sourceLabel:'IUCN Red List'},
{id:'albatroz-errante',name:'Albatroz-errante',sci:'Diomedea exulans',group:'Aves marinhas',depth:'Superfície–~10 m',habitat:'Oceano Antártico e mares do sul',size:'Envergadura de até ~3,5 m',status:'Vulnerável',type:'seabird',desc:'Ave marinha com a maior envergadura conhecida, capaz de percorrer milhares de quilômetros aproveitando o vento.',diet:'Lulas, peixes e carcaças capturados na superfície.',behavior:'Usa voo dinâmico sobre as ondas; alterna longos períodos no mar com reprodução em ilhas remotas.',threats:['captura em espinhéis','plásticos','espécies invasoras nas ilhas de reprodução'],facts:['O voo dinâmico aproveita gradientes de vento e gasta pouca energia.','Um único ciclo reprodutivo pode levar mais de um ano.','A mortalidade em anzóis de espinhel é uma das principais ameaças.'],source:'https://www.iucnredlist.org/',sourceLabel:'IUCN Red List'},
{id:'lula-colossal',name:'Lula-colossal',sci:'Mesonychoteuthis hamiltoni',group:'Moluscos',depth:'~300–2.000 m',habitat:'Oceano Antártico profundo',size:'Estimativas indicam grande massa corporal',status:'Pouco conhecida',type:'squid',desc:'Cefalópode antártico de corpo robusto, considerado o maior invertebrado conhecido em massa.',diet:'Peixes e outros cefalópodes.',behavior:'Vive em águas profundas do sul; é conhecido sobretudo por capturas incidentais e por restos encontrados em predadores.',threats:['conhecimento insuficiente'],facts:['Os tentáculos possuem ganchos giratórios além de ventosas.','Boa parte do que se sabe vem de conteúdos estomacais de cachalotes.','Poucos exemplares completos já foram examinados.'],source:'https://ocean.si.edu/ocean-life/invertebrates/octopuses-squids-and-relatives',sourceLabel:'Smithsonian Ocean'},
{id:'nautilo',name:'Náutilo',sci:'Nautilus pompilius',group:'Moluscos',depth:'~100–500 m',habitat:'Encostas recifais do Indo-Pacífico',size:'Concha de até ~20 cm',status:'Não avaliada globalmente',type:'nautilus',desc:'Cefalópode de concha externa espiralada, com câmaras cheias de gás que funcionam como sistema de flutuação.',diet:'Carniça, crustáceos e restos capturados por dezenas de tentáculos.',behavior:'Sobe à noite para se alimentar em águas mais rasas e desce durante o dia.',threats:['coleta para comércio de conchas','pesca incidental'],facts:['A concha é dividida em câmaras conectadas por um sifúnculo.','Diferente de polvos e lulas, não possui bolsa de tinta nem ventosas.','O grupo tem um longo registro fóssil de linhagens aparentadas.'],source:'https://ocean.si.edu/',sourceLabel:'Smithsonian Ocean'},
{id:'sepia-comum',name:'Sépia-comum',sci:'Sepia officinalis',group:'Moluscos',depth:'0–200 m',habitat:'Fundos arenosos do Atlântico Oriental e Mediterrâneo',size:'Manto de até ~45 cm',status:'Pouco preocupante',type:'octopus',desc:'Cefalópode de fundo com controle refinado da pele, capaz de mudar cor e textura em fração de segundo.',diet:'Crustáceos e peixes pequenos capturados com dois tentáculos rápidos.',behavior:'Camufla-se sobre o sedimento e usa padrões de pele em caça, defesa e comunicação.',threats:['pesca','alteração de fundos costeiros'],facts:['A sépia interna é uma estrutura porosa usada no controle de flutuação.','Cromatóforos, irodóforos e leucóforos combinam-se para gerar padrões.','A visão é sensível à polarização da luz.'],source:'https://ocean.si.edu/',sourceLabel:'Smithsonian Ocean'},
{id:'polvo-dumbo',name:'Polvo-dumbo',sci:'Grimpoteuthis spp.',group:'Moluscos',depth:'~1.000–4.000 m',habitat:'Fundo oceânico profundo',size:'Geralmente 20–30 cm',status:'Pouco conhecido',type:'octopus',desc:'Polvo de águas profundas com duas nadadeiras em forma de orelha, usadas para pairar próximo ao fundo.',diet:'Invertebrados bentônicos, engolidos inteiros.',behavior:'Move-se lentamente sobre o sedimento, alternando batidas de nadadeira e pulsos do manto.',threats:['conhecimento insuficiente','impactos potenciais de mineração em mar profundo'],facts:['Está entre os polvos que vivem nas maiores profundidades já registradas.','Não possui bolsa de tinta — a defesa por tinta perde função no escuro.','A maior parte dos registros vem de vídeos de veículos submarinos.'],source:'https://www.mbari.org/',sourceLabel:'MBARI'},
{id:'lula-vampira',name:'Lula-vampira',sci:'Vampyroteuthis infernalis',group:'Moluscos',depth:'~600–1.200 m',habitat:'Zona de mínimo de oxigênio',size:'Até ~30 cm',status:'Pouco conhecida',type:'squid',desc:'Cefalópode de linhagem própria, que vive em águas pobres em oxigênio e se alimenta de detritos em suspensão.',diet:'Neve marinha e agregados de matéria orgânica.',behavior:'Estende filamentos para coletar partículas; em ameaça, inverte o manto expondo espinhos moles.',threats:['conhecimento insuficiente'],facts:['Apesar do nome, não é predadora ativa: alimenta-se de detritos.','Tolera concentrações de oxigênio muito baixas.','Libera muco luminoso em vez de tinta.'],source:'https://www.mbari.org/',sourceLabel:'MBARI'},
{id:'caranguejo-aranha-japones',name:'Caranguejo-aranha-japonês',sci:'Macrocheira kaempferi',group:'Crustáceos',depth:'~150–800 m',habitat:'Fundos do Pacífico Noroeste',size:'Até ~3,7 m entre as pernas',status:'Pouco conhecido',type:'crab',desc:'Artrópode marinho com a maior distância entre pernas conhecida, associado a fundos profundos e frios.',diet:'Carniça, invertebrados e material orgânico do fundo.',behavior:'Anda lentamente pelo sedimento; sobe a águas mais rasas em época reprodutiva.',threats:['pesca em algumas regiões'],facts:['A carapaça é relativamente pequena comparada ao comprimento das pernas.','Pode viver por muitas décadas.','É frequentemente citado como exemplo de gigantismo em águas frias e profundas.'],source:'https://ocean.si.edu/',sourceLabel:'Smithsonian Ocean'},
{id:'lagosta-espinhosa',name:'Lagosta-espinhosa',sci:'Panulirus argus',group:'Crustáceos',depth:'0–90 m',habitat:'Recifes e fundos do Caribe e Atlântico ocidental',size:'Até ~45 cm',status:'Depende do estoque avaliado',type:'crab',desc:'Crustáceo recifal sem pinças grandes, conhecido por migrações em fila indiana e por longas antenas defensivas.',diet:'Moluscos, crustáceos e material do fundo.',behavior:'Abriga-se em fendas durante o dia e forrageia à noite; forma filas migratórias sazonais.',threats:['sobrepesca','perda de habitat recifal','doenças'],facts:['As filas migratórias reduzem o arrasto e a exposição a predadores.','Usa as antenas e sons de fricção como defesa.','As larvas passam meses no plâncton antes de se fixarem.'],source:'https://www.fao.org/fishery/en',sourceLabel:'FAO Fisheries'},
{id:'krill-antartico',name:'Krill-antártico',sci:'Euphausia superba',group:'Crustáceos',depth:'0–500 m',habitat:'Oceano Antártico',size:'Até ~6 cm',status:'Pouco preocupante',type:'shrimp',desc:'Crustáceo pequeno e abundante que concentra energia do fitoplâncton e sustenta grande parte da teia alimentar antártica.',diet:'Fitoplâncton, incluindo algas associadas ao gelo marinho.',behavior:'Forma enxames densos e realiza migração vertical diária.',threats:['pesca de krill','redução do gelo marinho','acidificação'],facts:['Baleias, focas, pinguins e peixes dependem diretamente da sua abundância.','As larvas usam algas do gelo marinho como alimento no inverno.','Enxames podem ser detectados por sonar e por satélite.'],source:'https://www.ccamlr.org/',sourceLabel:'CCAMLR'},
{id:'isopode-gigante',name:'Isópode-gigante',sci:'Bathynomus giganteus',group:'Crustáceos',depth:'~300–2.100 m',habitat:'Fundo do Atlântico ocidental profundo',size:'Até ~40 cm',status:'Pouco conhecido',type:'isopod',desc:'Crustáceo detritívoro de fundo profundo, aparentado dos tatuzinhos-de-jardim, com corpo segmentado e blindado.',diet:'Carcaças que afundam e material orgânico do fundo.',behavior:'Move-se lentamente e pode passar longos períodos sem se alimentar entre eventos de carniça.',threats:['conhecimento insuficiente'],facts:['É um exemplo clássico de gigantismo em ambientes profundos.','Grandes carcaças que afundam podem alimentar dezenas de indivíduos.','Consegue sobreviver por meses entre refeições em cativeiro.'],source:'https://ocean.si.edu/',sourceLabel:'Smithsonian Ocean'},
{id:'medusa-lua',name:'Medusa-lua',sci:'Aurelia aurita',group:'Cnidários',depth:'0–200 m',habitat:'Águas costeiras de quase todo o mundo',size:'Umbrela de até ~40 cm',status:'Não avaliada globalmente',type:'jelly',desc:'Cifozoário translúcido, comum em baías e estuários, com ciclo de vida alternando pólipo fixo e medusa livre.',diet:'Zooplâncton capturado por muco e tentáculos curtos.',behavior:'Deriva com as correntes, pulsando a umbrela para se manter na coluna d’água.',threats:['alterações costeiras'],facts:['As quatro estruturas em forma de ferradura visíveis na umbrela são gônadas.','O pólipo fixo pode produzir várias medusas por estrobilização.','Agregações costeiras podem aumentar em ambientes alterados.'],source:'https://ocean.si.edu/',sourceLabel:'Smithsonian Ocean'},
{id:'coral-chifre-de-alce',name:'Coral-chifre-de-alce',sci:'Acropora palmata',group:'Cnidários',depth:'1–20 m',habitat:'Recifes rasos do Caribe',size:'Colônias de até ~3 m',status:'Criticamente em perigo',type:'coral',desc:'Coral construtor de ramos largos que historicamente formou a estrutura das cristas recifais do Caribe.',diet:'Simbiose com algas fotossintetizantes, complementada por captura de plâncton.',behavior:'Cresce rapidamente em águas rasas e agitadas; reproduz-se por desova sincronizada e por fragmentação.',threats:['branqueamento','doenças','sedimentação e poluição costeira'],facts:['Abriga zooxantelas, algas simbiontes que fornecem grande parte da energia da colônia.','A estrutura ramificada reduz a energia das ondas que chega à costa.','Populações caribenhas sofreram declínios acentuados desde os anos 1980.'],source:'https://coral.org/',sourceLabel:'Coral Reef Alliance'},
{id:'estrela-do-mar-girassol',name:'Estrela-do-mar-girassol',sci:'Pycnopodia helianthoides',group:'Equinodermos',depth:'0–435 m',habitat:'Costa do Pacífico Nordeste',size:'Até ~1 m de diâmetro',status:'Criticamente em perigo',type:'star',desc:'Grande estrela-do-mar predadora, com muitos braços, cujo colapso populacional afetou florestas de kelp inteiras.',diet:'Ouriços, moluscos e outros invertebrados do fundo.',behavior:'Move-se relativamente rápido para um equinodermo, usando milhares de pés ambulacrais.',threats:['doença de desgaste de estrelas-do-mar','ondas de calor marinhas'],facts:['Pode chegar a mais de vinte braços na fase adulta.','A perda desse predador contribuiu para a expansão de áreas dominadas por ouriços.','A epidemia registrada a partir de 2013 reduziu populações em grande parte da costa.'],source:'https://www.iucnredlist.org/',sourceLabel:'IUCN Red List'},
{id:'ourico-do-mar-roxo',name:'Ouriço-do-mar-roxo',sci:'Strongylocentrotus purpuratus',group:'Equinodermos',depth:'0–90 m',habitat:'Costões rochosos do Pacífico Nordeste',size:'Até ~10 cm',status:'Não avaliado globalmente',type:'urchin',desc:'Ouriço herbívoro cuja densidade populacional ajuda a determinar se uma costa terá floresta de kelp ou fundo raspado.',diet:'Algas, especialmente kelp.',behavior:'Escava depressões na rocha e pode entrar em estado de baixo metabolismo quando falta alimento.',threats:['desequilíbrios tróficos','ondas de calor marinhas'],facts:['A estrutura bucal com cinco dentes é chamada lanterna de Aristóteles.','Densidades altas podem criar “desertos de ouriços” sem kelp.','É um organismo-modelo importante em biologia do desenvolvimento.'],source:'https://ocean.si.edu/',sourceLabel:'Smithsonian Ocean'},
{id:'porco-do-mar',name:'Porco-do-mar',sci:'Scotoplanes globosa',group:'Equinodermos',depth:'~1.000–6.000 m',habitat:'Planícies abissais',size:'Até ~15 cm',status:'Pouco conhecido',type:'seacucumber',desc:'Pepino-do-mar abissal que caminha pelo sedimento sobre pés ambulacrais alongados, processando detritos do fundo.',diet:'Matéria orgânica depositada no sedimento.',behavior:'Move-se em grupos sobre a lama abissal, concentrando-se onde chega alimento fresco.',threats:['impactos potenciais de mineração em mar profundo'],facts:['Detecta quimicamente depósitos recentes de matéria orgânica.','É um dos animais mais abundantes em algumas planícies abissais.','Ao revolver o sedimento, participa da ciclagem de carbono do fundo.'],source:'https://www.mbari.org/',sourceLabel:'MBARI'},
{id:'peixe-vibora',name:'Peixe-víbora',sci:'Chauliodus sloani',group:'Águas profundas',depth:'~200–2.000 m',habitat:'Zona mesopelágica e batipelágica',size:'Até ~35 cm',status:'Pouco conhecido',type:'angler',desc:'Predador mesopelágico de dentes desproporcionais e fotóforos ao longo do corpo.',diet:'Peixes pequenos e crustáceos.',behavior:'Sobe à noite acompanhando a migração vertical das presas; ataca por emboscada.',threats:['conhecimento insuficiente'],facts:['Os dentes são longos demais para caber dentro da boca fechada.','Uma fileira de fotóforos ventrais ajuda a quebrar a silhueta contra a luz que vem de cima.','A dieta depende diretamente da migração vertical diária.'],source:'https://www.mbari.org/',sourceLabel:'MBARI'},
{id:'peixe-dragao',name:'Peixe-dragão-negro',sci:'Malacosteus niger',group:'Águas profundas',depth:'~500–2.000 m',habitat:'Zona mesopelágica e batipelágica',size:'Até ~25 cm',status:'Pouco conhecido',type:'angler',desc:'Peixe profundo capaz de emitir e enxergar luz vermelha, uma faixa quase invisível para a maioria dos animais do local.',diet:'Copépodes, crustáceos e pequenos peixes.',behavior:'Usa fotóforos vermelhos como um “holofote privado” para localizar presas sem ser detectado.',threats:['conhecimento insuficiente'],facts:['A sensibilidade ao vermelho depende de um pigmento derivado de clorofila obtido na dieta.','A maioria dos organismos mesopelágicos não enxerga luz vermelha.','Possui também fotóforos azuis, mais comuns em peixes profundos.'],source:'https://ocean.si.edu/ocean-life/fish/bioluminescence',sourceLabel:'Smithsonian Ocean'},
{id:'verme-tubo-gigante',name:'Verme-tubo-gigante',sci:'Riftia pachyptila',group:'Águas profundas',depth:'~1.500–3.300 m',habitat:'Fontes hidrotermais do Pacífico Oriental',size:'Tubos de até ~2 m',status:'Pouco conhecido',type:'worm',desc:'Verme de fontes hidrotermais que não possui boca nem intestino: obtém energia de bactérias simbiontes internas.',diet:'Nutrição por simbiose: bactérias quimiossintetizantes alojadas no trofossoma.',behavior:'Vive fixo em tubos próximos a fluidos quentes, expondo a pluma vermelha para captar gases.',threats:['mineração potencial em mar profundo','alteração de fontes hidrotermais'],facts:['A pluma vermelha contém hemoglobina que transporta oxigênio e sulfeto ao mesmo tempo.','As bactérias internas convertem compostos de enxofre em matéria orgânica.','As colônias podem crescer rapidamente após a abertura de novas fontes.'],source:'https://www.whoi.edu/',sourceLabel:'Woods Hole Oceanographic Institution'},
{id:'prochlorococcus',name:'Prochlorococcus',sci:'Prochlorococcus marinus',group:'Plâncton e micro-organismos',depth:'0–200 m',habitat:'Águas oceânicas quentes e pobres em nutrientes',size:'Menos de 1 µm',status:'Não se aplica',type:'plankton',desc:'Cianobactéria fotossintetizante extremamente pequena e abundante, responsável por uma fração significativa da fotossíntese oceânica.',diet:'Fotossíntese.',behavior:'Domina as camadas iluminadas dos giros oceânicos; linhagens diferentes ocupam profundidades diferentes.',threats:['alterações na estratificação e na temperatura do oceano'],facts:['Só foi descrita no fim dos anos 1980, apesar da enorme abundância.','Ecotipos distintos são adaptados a intensidades de luz diferentes.','É um dos organismos fotossintetizantes mais numerosos do planeta.'],source:'https://www.whoi.edu/',sourceLabel:'Woods Hole Oceanographic Institution'},
{id:'diatomaceas',name:'Diatomáceas',sci:'Bacillariophyceae',group:'Plâncton e micro-organismos',depth:'0–200 m',habitat:'Zona iluminada de todos os oceanos',size:'Geralmente 2–200 µm',status:'Não se aplica',type:'plankton',desc:'Microalgas com parede de sílica que respondem por grande parte da produção primária marinha, sobretudo em águas ricas em nutrientes.',diet:'Fotossíntese.',behavior:'Formam florações rápidas quando luz e nutrientes coincidem; ao afundar, transportam carbono para o fundo.',threats:['alterações na disponibilidade de nutrientes','aquecimento e estratificação'],facts:['A carapaça de sílica é chamada frústula e tem estrutura simétrica intrincada.','Florações sazonais sustentam desde krill até baleias.','O afundamento das células é parte importante da bomba biológica de carbono.'],source:'https://oceanservice.noaa.gov/',sourceLabel:'NOAA Ocean Service'},
{id:'kelp-gigante',name:'Kelp-gigante',sci:'Macrocystis pyrifera',group:'Algas e plantas marinhas',depth:'0–40 m',habitat:'Costas temperadas frias e produtivas',size:'Pode ultrapassar 30 m',status:'Depende da região avaliada',type:'kelp',desc:'Alga parda de crescimento muito rápido que forma florestas submersas e cria estrutura tridimensional para centenas de espécies.',diet:'Fotossíntese; fixa-se ao substrato por um apressório.',behavior:'Mantém as lâminas próximas à superfície graças a flutuadores cheios de gás.',threats:['ondas de calor marinhas','herbivoria excessiva por ouriços','sedimentação'],facts:['Está entre os organismos de crescimento mais rápido conhecidos.','O apressório fixa a alga à rocha, mas não absorve nutrientes como raiz.','A floresta reduz a energia das ondas e abriga peixes, invertebrados e mamíferos marinhos.'],source:'https://ocean.si.edu/',sourceLabel:'Smithsonian Ocean'},
{id:'anfipode-hadal',name:'Anfípode-hadal',sci:'Hirondellea gigas',group:'Crustáceos',depth:'~6.000–11.000 m',habitat:'Fossas oceânicas do Pacífico',size:'Poucos centímetros',status:'Pouco conhecido',type:'shrimp',desc:'Pequeno crustáceo detritívoro que domina o fundo das fossas mais profundas, onde poucos animais conseguem viver.',diet:'Matéria orgânica depositada e carcaças que afundam.',behavior:'Aparece rapidamente em grande número quando alimento chega ao fundo da fossa.',threats:['conhecimento insuficiente'],facts:['É uma das presas principais dos peixes registrados em fossas profundas.','Possui enzimas capazes de digerir material vegetal que afunda da superfície.','Domina as armadilhas iscadas colocadas abaixo de 6.000 m.'],source:'https://www.whoi.edu/',sourceLabel:'Woods Hole Oceanographic Institution'},
{id:'peixe-gota',name:'Peixe-gota',sci:'Psychrolutes marcidus',group:'Águas profundas',depth:'~600–1.200 m',habitat:'Fundos profundos ao largo da Austrália e Tasmânia',size:'Até ~30 cm',status:'Pouco conhecido',type:'fish',desc:'Peixe bentônico de carne gelatinosa e pouca musculatura, adaptado a se manter próximo ao fundo sem gastar energia.',diet:'Invertebrados e material capturado junto ao sedimento.',behavior:'Permanece quase imóvel sobre o fundo, esperando que presas passem ao alcance.',threats:['captura incidental em pesca de arrasto profundo'],facts:['A densidade do corpo é pouco menor que a da água, o que dispensa bexiga natatória.','O aspecto “derretido” das fotos aparece após a descompressão na superfície.','No próprio habitat, o corpo mantém contorno bem mais definido.'],source:'https://www.marinespecies.org/',sourceLabel:'WoRMS'}
];
